  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0} : « Cette cure va faire de toi un monstre pendant {1} combats. Ça ne se voit pas aux contrôles… en général. » Le prix : {2}.\n\nSi tu acceptes, ta frappe, ton cardio, ta vitesse et ton menton grimpent fortement. Si tu te fais prendre : suspension de 6 mois à 2 ans, popularité perdue et sponsors annulés.",
  "Kabul et": "Accepter",
  "Federasyona ihbar et": "Signaler à la commission",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "Tu as pris la cure. Il y a quelqu'un d'autre dans le miroir. Tu es très fort pour les {0} prochains combats… mais chaque combat comporte un risque de contrôle.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "Tu as poliment refusé. Une carrière propre, un sommeil paisible.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "Tu l'as signalé à la commission. La presse t'a appelé « la voix du sport propre ». Popularité +2.",
  "💼 Sponsorluk Teklifi": "💼 Offre de sponsoring",
  "Bahis": "Paris",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nMais c'est une société de paris… Certains fans pourraient ne pas apprécier.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} veut travailler avec toi. Leurs logos seront sur ton short, et ils te paieront {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Négocier (tenter +50 %)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Certains fans sont mécontents : popularité -2)",
  "{0} ile anlaştın. +{1}{2}": "Tu as signé avec {0}. +{1}{2}",
  "Sıkı pazarlık işe yaradı! +{0}": "La négociation serrée a payé ! +{0}",
  "{0} masadan kalktı. \"Başka dövüşçüler de var.\"": "{0} est parti. « Il y a d'autres combattants. »",
  "Teklifi reddettin. İmajın temiz kaldı.": "Tu as refusé l'offre. Ton image reste propre.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "Une vidéo où tu mets KO ton partenaire de sparring a atteint 2 millions de vues. Les commentaires sont partagés. Que publies-tu ?",
  "Sıklettekilere laf at": "Défier toute la catégorie",
  "Mütevazı bir teşekkür yaz": "Écrire un merci humble",
  "Görmezden gel": "Ignorer",
  "Paylaşımın ortalığı yıktı. Rakipler cevap yazıyor, gazeteciler seni arıyor. Popülerlik +5.": "Ton post a explosé. Les rivaux répondent, les journalistes appellent. Popularité +5.",
  "Kibirli buldular. \"Önce bir kemer kazan\" yorumları ağır bastı. Popülerlik -3.": "On l'a trouvé arrogant. Les commentaires « Gagne d'abord une ceinture » ont tout envahi. Popularité -3.",
  "Samimi mesajın sevildi. Popülerlik +2.": "Ton message sincère a été adoré. Popularité +2.",
  "Hiçbir şey yazmadın. Video kendi kendine yayılmaya devam etti. Popülerlik +1.": "Tu n'as rien publié. La vidéo a continué à circuler toute seule. Popularité +1.",
  "🏟️ Salon Değiştirme Fırsatı": "🏟️ Une occasion de changer de salle",
  "{0} baş antrenörü {1} seni takımında görmek istiyor (kalite {2}/10). Davetli olduğun için geçiş ücreti yarı fiyat: {3}.\n\nŞu anki hocan {4} (kalite {5}/10) seni sıfırdan yetiştirdi.": "L'entraîneur principal de {0}, {1}, te veut dans son équipe (qualité {2}/10). Comme tu es invité, le transfert est à moitié prix : {3}.\n\nTon entraîneur actuel {4} (qualité {5}/10) t'a construit de zéro.",
  "Taşın": "Partir",
  "Kal, sadakat önemli": "Rester, la loyauté compte",
  "Paran yetmiyor ({0} gerekli). Fırsat kaçtı.": "Tu n'en as pas les moyens ({0} nécessaires). L'occasion est passée.",
  "Yeni evin: {0}. {1} telefonda sessizce \"Başarılar evlat\" dedi ve kapattı.": "Ta nouvelle maison : {0}. Au téléphone, {1} a dit doucement « Bonne chance, petit » et a raccroché.",
  "Kaldın. Hocan gözleri dolarak sarıldı. Sonraki kampta ekstra motivasyonla çalışacaksın.": "Tu es resté. Ton entraîneur t'a serré dans ses bras, les larmes aux yeux. Tu t'entraîneras avec une motivation de plus au prochain camp.",
