  "— {0}. RAUNT — Sen: {1}": "— ROUND {0} — Toi : {1}",
  "🧠 {0} bu hamleyi bekliyordu. Aynı oyunu {1}. kez oynamak seni öngörülebilir yapıyor.": "🧠 {0} attendait ce mouvement. Jouer la même carte ({1} fois maintenant) te rend prévisible.",
