  "🔥 {0} yağmur gibi yumruk indiriyor, {1} karşılık veremiyor, hakem araya giriyor! TKO!": "🔥 {0} fait pleuvoir les coups, {1} ne peut pas répondre, l'arbitre intervient ! TKO !",
  "😱 {0} umutsuz bir kontra savurdu ve TAM İSABET! Durum tersine döndü!": "😱 {0} a lancé un contre désespéré et l'a PLACÉ EN PLEIN ! La situation s'est inversée !",
  "{0} bir şekilde ayakta kaldı, zili bekliyor. Sen de çok yoruldun.": "{0} est resté debout on ne sait comment, en attendant la cloche. Toi aussi tu es épuisé.",
  "🎯 {0} hedef seçerek vuruyor, sağ-sol-sağ… hakem yeter diyor! TKO!": "🎯 {0} choisit ses coups, droite-gauche-droite… l'arbitre en a assez vu ! TKO !",
  "{0} kontrollü vuruşlarla puan topluyor, rakip toparlanmaya çalışıyor.": "{0} marque avec des frappes contrôlées pendant que son adversaire tente de récupérer.",
  "{0} yere indirmek için daldı ama rakip son gücüyle savundu. Fırsat kaçtı.": "{0} a tenté une amenée au sol mais l'adversaire a défendu avec tout ce qui lui restait. L'occasion est passée.",
  "🔨 {0} yerde mount aldı, ground and pound yağdırıyor, hakem durdurdu! TKO!": "🔨 {0} a pris la montée au sol et a fait pleuvoir le ground and pound, l'arbitre a arrêté ! TKO !",
  "🔒 {0} sersem rakibin sırtını aldı ve {1} ile tap attırdı!": "🔒 {0} a pris le dos de l'adversaire sonné et l'a fait taper avec {1} !",
  "{0} yerde ağır vuruyor ama {1} bir şekilde hayatta kalıyor.": "{0} place de gros coups au sol mais {1} survit on ne sait comment.",
