  "Karşılık vermeye çalıştın, isabet etmedi ama o da bitiremedi. Hayattasın!": "Tu as tenté de répliquer, ça n'a pas touché, mais il n'a pas pu finir non plus. Tu as survécu !",
  "💀 {0} son darbeyi indirdi. Bilinçsiz yere yığıldın. NAKAVT.": "💀 {0} a placé le dernier coup. Tu t'es effondré inconscient. KO.",
  "💀 {0} yumruk yağdırıyor, kendini savunamıyorsun. Hakem durdurdu. TKO.": "💀 {0} fait pleuvoir les coups, tu ne peux plus te défendre. L'arbitre a arrêté. TKO.",
  "Ağır darbeler aldın ama ayaktasın. Zil seni kurtarmak zorunda.": "Tu as pris de gros coups mais tu tiens debout. La cloche doit te sauver.",
  "🔒 {0} {1} kilidini sonuna kadar sıktı… {2} TAP ATTI!": "🔒 {0} a serré {1} jusqu'au bout… {2} A TAPÉ !",
