  "Kampın {n}. haftası. Ciğerler yanıyor ama zihin berrak. 🥊": "Semaine {n} de camp. Les poumons brûlent mais l'esprit est clair. 🥊",
  "Sabah 5’te koşu, öğlen spar, akşam grappling. {rakip}, ben hazırım. #Kamp": "Footing à 5 h, sparring à midi, grappling le soir. {rakip}, je suis prêt. #Camp",
  "{hoca} bugün beni yere serdi. Kafeste kimse bunu yapamayacak. 😤": "{hoca} m'a mis au tapis aujourd'hui. Personne dans la cage n'y arrivera. 😤",
  "Yeni bir silah geliştiriyoruz. Maç gecesi göreceksiniz… 🤫": "On construit une nouvelle arme. Vous la verrez le soir du combat… 🤫",
  "Kilo kontrolde, zihin net. {rakip} gelsin.": "Poids sous contrôle, esprit clair. Amenez-moi {rakip}.",
  "{salon}’da bir gece daha. Işıklar sönene kadar buradayım. 💡": "Encore une soirée à {salon}. Je reste jusqu'à ce que les lumières s'éteignent. 💡",
  "Bugün 10 raunt spar. Yoruldum ama durmadım.": "10 rounds de sparring aujourd'hui. Fatigué mais je ne me suis pas arrêté.",
  "Video analiz günü: {rakip}’in her hareketini ezberliyorum. 🎬": "Journée vidéo : j'apprends par cœur chaque mouvement de {rakip}. 🎬",
  "Buz banyosu, masaj, uyku. Savaşçı dinlenmeyi de bilir. 🧊": "Bain glacé, massage, sommeil. Un guerrier sait aussi se reposer. 🧊",
  "Kamp güncellemesi: sağlıklı, aç ve tehlikeli. 🐺": "Nouvelles du camp : en forme, affamé et dangereux. 🐺",
  "{rakip} kafeste beni görünce kaçacak yer arayacak. 😂": "{rakip} va chercher une sortie quand il me verra dans la cage. 😂",
  "{rakip}, sosyal medyada çok cesursun. Kafeste görüşürüz.": "{rakip}, tu es très courageux sur les réseaux. On se voit dans la cage.",
  "Bu gece {rakip} uyumayacak. Çünkü maç gecesi uyutacağım. 💤": "{rakip} ne dormira pas cette nuit. Parce que c'est moi qui l'endormirai le soir du combat. 💤",
  "{rakip} diye bir dövüşçü yok, sadece bir sonraki kurbanım var.": "Il n'y a pas de combattant nommé {rakip}, juste ma prochaine victime.",
  "{rakip} hayranları, şimdiden mendilleri hazırlayın. 🤧": "Fans de {rakip}, préparez vos mouchoirs. 🤧",
  "{rakip}’in çenesi o kadar dayanıklı değil, herkes biliyor.": "Le menton de {rakip} n'est pas si solide, tout le monde le sait.",
  "Kamera önünde herkes aslan. Kafes kapısı kapanınca görürüz {rakip}.": "Tout le monde est un lion devant la caméra. On verra quand la porte de la cage se fermera, {rakip}.",
  "{rakip}, hazır ol. Kariyerinin en kötü gecesi yaklaşıyor.": "{rakip}, prépare-toi. La pire soirée de ta carrière arrive.",
  "Söylediklerimin arkasındayım: {rakip} bu maçı bitiremeyecek.": "Je maintiens : {rakip} ne finira pas ce combat.",
  "{sampiyon}, kemerini hazırla. Geliyorum. 🏆": "{sampiyon}, prépare ta ceinture. J'arrive. 🏆",
  "{sampiyon} benden kaçıyor. {org}, bu maçı yapın!": "{sampiyon} me fuit. {org}, organisez ce combat !",
  "Sıklette kimse benimle dövüşmek istemiyor. Sıradaki kim? 👀": "Personne dans la catégorie ne veut m'affronter. Au suivant ? 👀",
  "{sampiyon}, tahtında rahat oturma. Sıra bende.": "{sampiyon}, ne t'installe pas trop sur ce trône. Je suis le prochain.",
  "İlk 5’e giren herkese açık davet: kafeste görüşelim.": "Invitation ouverte à tout le top 5 : on se voit dans la cage.",
  "{org}, bana bir şampiyonluk maçı borçlusunuz. Hak ettim.": "{org}, vous me devez un combat pour le titre. Je l'ai mérité.",
  "Adımı unutmayın. Yakında o kemer bende olacak.": "Souvenez-vous de mon nom. Bientôt cette ceinture sera à moi.",
  "{rakip} gerçek bir savaşçı. Maç gecesi en iyi hâlimizle karşılaşacağız. 🤝": "{rakip} est un vrai guerrier. On se retrouvera au meilleur de notre forme le soir du combat. 🤝",
  "Rakibime saygım sonsuz. Ama kazanan ben olacağım.": "Respect infini pour mon adversaire. Mais c'est moi qui gagnerai.",
  "{hoca} ve tüm takımıma teşekkürler. Bu yol tek başına yürünmez.": "Merci à {hoca} et à toute mon équipe. Personne ne fait ce chemin seul.",
  "Sıklette herkes çok çalışıyor. Bu yüzden bu spor güzel.": "Tout le monde travaille dur dans la catégorie. C'est ce qui rend ce sport si beau.",
  "Yenildiğim her maç bana bir şey öğretti. Hepsine minnettarım.": "Chaque défaite m'a appris quelque chose. Je suis reconnaissant pour chacune.",
  "Rakiplerime saygı, taraftarlara sevgi. Gerisi kafeste. 🙏": "Respect à mes adversaires, amour aux fans. Le reste se passe dans la cage. 🙏",
  "{takipci} kişi! İnanılmaz. Her birinize teşekkür ederim. ❤️": "{takipci} personnes ! Incroyable. Merci, à chacun d'entre vous. ❤️",
  "Maç gecesi tribünler yine bizim olsun! Kim geliyor? 🙌": "Reprenons les tribunes le soir du combat ! Qui vient ? 🙌",
  "Bir taraftarım bugün bana el yazısı mektup verdi. Ağladım. 🥹": "Un fan m'a donné une lettre écrite à la main aujourd'hui. J'ai pleuré. 🥹",
  "{memleket}, bu zafer senin için!": "{memleket}, cette victoire est pour toi !",
  "Sorularınızı yazın, en iyilerini bu akşam cevaplayacağım. 👇": "Posez vos questions, je réponds aux meilleures ce soir. 👇",
  "Bu yolculukta yanımda olan herkese: sizin sayenizde buradayım.": "À tous ceux qui m'accompagnent dans cette aventure : je suis là grâce à vous.",
  "Kimse sana inanmasa da sen kendine inan. 💯": "Crois en toi même quand personne d'autre n'y croit. 💯",
  "Ter antrenmanda akar ki kan kafeste akmasın.": "Transpire à l'entraînement pour ne pas saigner dans la cage.",
  "Düştüğün yer değil, kalktığın yer seni tanımlar.": "Ce n'est pas là où tu tombes, c'est là où tu te relèves qui te définit.",
  "Bugün acı, yarın zafer. 🔥": "La douleur aujourd'hui, la victoire demain. 🔥",
  "Yetenek başlatır, disiplin bitirir.": "Le talent commence le travail, la discipline le termine.",
  "Her sabah aynı soru: bugün dünden daha iyi miyim?": "La même question chaque matin : suis-je meilleur qu'hier ?",
  "Kolay olsaydı herkes şampiyon olurdu.": "Si c'était facile, tout le monde serait champion.",
  "Bugün dinlenme günü. Ailemle kahvaltı. Savaşçılar da insan. ❤️": "Jour de repos aujourd'hui. Petit-déjeuner en famille. Les guerriers aussi sont humains. ❤️",
  "Yeni tatlı yasak listesi: hepsi. 🍰❌": "Nouvelle liste des desserts interdits : tous. 🍰❌",
  "Bir kahve, biraz müzik, sonra tekrar salon. ☕🎧": "Un café, un peu de musique, puis retour à la salle. ☕🎧",
  "Hayatımda iki şey var: kafes ve sevdiklerim.": "Deux choses dans ma vie : la cage et ceux que j'aime.",
  "{sponsor} ile yola devam! Teşekkürler ekip. 🤝": "On continue avec {sponsor} ! Merci, l'équipe. 🤝",
  "Maç gecesi {sponsor} logosuyla kafesteyim. 💪": "Dans la cage le soir du combat avec le logo {sponsor}. 💪",
  "{sponsor} ailesine katılmak gurur verici. Birlikte zirveye!": "Fier de rejoindre la famille {sponsor}. Au sommet ensemble !",
  "Soru: sıradaki maçımı nakavtla mı bitireyim, submission ile mi? 👇": "Question : je finis mon prochain combat par KO ou par soumission ? 👇",
  "Sizce sıklette en tehlikeli isim kim? Yorumlara yazın.": "Selon vous, quel est le nom le plus dangereux de la catégorie ? Dites-le en commentaire.",
  "Tüm zamanların en iyisi kim sizce? Tartışalım. 🐐": "Qui est le plus grand de tous les temps ? Débattons. 🐐",
  "Maç gecesi hangi şarkıyla çıkayım? Önerilere açığım. 🎵": "Sur quelle chanson dois-je entrer le soir du combat ? Je suis ouvert aux suggestions. 🎵",
  "Hangi rakiple dövüşmemi istersiniz? En çok beğenilen yorumu {org}’a ileteceğim.": "Contre qui voulez-vous que je combatte ? Je transmettrai le commentaire le plus aimé à {org}.",
