  "Tatil bulunamadı.": "Vacances introuvables.",
  "Bu tatil için paran yetmiyor.": "Tu n'as pas les moyens de ces vacances.",
  "🛍️ {0}: {1} hafta tatil. Sağlık {2}/100.{3} {4}": "🛍️ {0} : {1} semaines de vacances. Santé {2}/100.{3} {4}",
  ", motivasyon {0}{1}": ", motivation {0}{1}",
  ", popülerlik +{0}": ", popularité +{0}",
  "\n⚠️ Disiplin bozuldu, form kaybı: {0}.": "\n⚠️ La discipline s'est relâchée, forme perdue : {0}.",
  "{0} bitti. Sağlık +{1}{2}{3}.{4}": "{0} est terminé. Santé +{1}{2}{3}.{4}",
  "{ph} ile aynı kafese girmek için sabırsızlanıyorum. Sabırsızlığım onun korkusundan büyük. 😈": "J'ai hâte d'entrer dans la cage avec {ph}. Mon impatience est plus grande que sa peur. 😈",
  "Kamp raporu: {ph} dövüşünü 100 kez izledim. Açığını buldum. Sürpriz olmayacak.": "Rapport du camp : j'ai regardé {ph} combattre 100 fois. J'ai trouvé la faille. Pas de surprise.",
  "Bahis tavsiyesi: {ph} aleyhine her şeyinizi yatırın. 💰": "Conseil de pari : misez tout contre {ph}. 💰",
  "{ph}’ın hocası bile bu maçı kabul ettiği için ona kızıyormuş. 😂": "Même l'entraîneur de {ph} lui en veut d'avoir accepté ce combat. 😂",
  "Tartıda göz göze geleceğiz {ph}. Gözlerini kaçırma.": "On se regardera dans les yeux à la pesée, {ph}. Ne détourne pas le regard.",
  "{ph} sıkletin en abartılı ismi. {hafta} hafta sonra balon patlıyor. 🎈": "{ph} est le nom le plus surcoté de la catégorie. Dans {hafta} semaines, la bulle éclate. 🎈",
  "{ph} mi? {org}’da bana verilen en kolay maç bu. {hafta} hafta sonra görürüz.": "{ph} ? Le combat le plus facile que {org} m'ait jamais donné. Rendez-vous dans {hafta} semaines.",
  "{ph} kafeste görüşürüz. Hastane masrafını ben öderim, merak etme.": "On se voit dans la cage, {ph}. Je paierai la note d'hôpital, t'inquiète.",
  "Çenen cam gibi {p}. İlk sağ elimde dağılacak.": "Ton menton est en verre, {p}. Il volera en éclats à ma première droite.",
  "{ph} sosyal medyada çok cesur. Bakalım kafes kapısı kapanınca da öyle mi?": "{ph} est très courageux sur les réseaux. Voyons si ça tient quand la porte de la cage se fermera.",
  "Herkes {p} diyor… Ben kimseyi görmüyorum. 🥱": "Tout le monde parle de {p}… moi je ne vois personne. 🥱",
  "{ph} taraftarlarına söyleyin, mendillerini hazırlasınlar.": "Dites aux fans de {ph} de préparer leurs mouchoirs.",
  "{ph} kariyerini takip ediyorum, ciddi bir yetenek. Ama bu gece benim gecem olacak.": "J'ai suivi la carrière de {ph}, un vrai talent. Mais ce soir, ce sera mon soir.",
  "Bu maç ikimiz için de büyük fırsat. {ph}, sağlıklı bir kamp dilerim.": "Ce combat est une grande opportunité pour nous deux. {ph}, bon camp à toi.",
  "{ph} ile dövüşmek onur. Hazırlığım tam, en iyi hâlimle geleceğim.": "Un honneur d'affronter {ph}. Ma préparation est terminée, j'arrive au meilleur de ma forme.",
  "Saygı duyduğum bir rakip: {ph}. Ama kazanan ben olacağım.": "Un adversaire que je respecte : {ph}. Mais c'est moi qui gagnerai.",
  "Kamp bitti. {ph}, iyi bir savaş olsun. 🤝": "Le camp est terminé. {ph}, faisons une belle guerre. 🤝",
  "{ph} söylemiştim. Sıradaki! 👋": "Je te l'avais dit, {ph}. Au suivant ! 👋",
  "Bu gece bir şey kanıtladım. {ph}, iyi dövüştün ama yeterli değildi.": "J'ai prouvé quelque chose ce soir. {ph}, tu t'es bien battu mais ça n'a pas suffi.",
  "Kemer yolu devam ediyor. {ph} sadece bir basamaktı.": "La route vers la ceinture continue. {ph} n'était qu'une marche.",
  "{ph} bu gece daha iyiydi. Tebrikler şampiyon adayı. Geri döneceğim.": "{ph} était meilleur ce soir. Bravo, futur champion. Je reviendrai.",
  "Ders aldım. {ph} gerçek bir savaşçı. 🤝": "Leçon retenue. {ph} est un vrai guerrier. 🤝",
  "Hakemler bu gece beni soydu. {ph} bunu biliyor.": "Les juges m'ont volé ce soir. {ph} le sait.",
  "Şanslı yumruktu {ph}. Rövanşta gerçeği göreceksin.": "Coup de chance, {ph}. Tu verras la vérité à la revanche.",
  "Tek kelime: RÖVANŞ. {ph} kaçmasın.": "Un mot : REVANCHE. {ph}, ne fuis pas.",
  "{p} maçını 5. kez izliyorum, hâlâ doyamadım 🔥": "Je regarde le combat de {p} pour la 5e fois, je ne m'en lasse pas 🔥",
  "Babam 40 yıldır maç izler, “böylesini görmedim” dedi.": "Mon père regarde des combats depuis 40 ans et il a dit : « Je n'ai jamais rien vu de pareil. »",
  "Bu adamın posteri odamda artık 🥊": "Le poster de ce combattant est sur mon mur maintenant 🥊",
  "{p} sıkletin geleceği değil, bugünü!": "{p} n'est pas l'avenir de la catégorie, c'est le présent !",
  "O kombinasyon ne öyle?! Geri sar, geri sar!": "C'était quoi cet enchaînement ?! Rembobinez, rembobinez !",
  "Salon arkadaşlarımla izledik, ortalık yıkıldı 😂": "Regardé avec mes potes de la salle, c'était la folie 😂",
  "{p} geleceğin şampiyonu!! 🔥🔥": "{p} est un futur champion !! 🔥🔥",
  "Bu adamı izlemek bir zevk. Kemer an meselesi.": "Un plaisir à regarder. La ceinture n'est qu'une question de temps.",
  "{memleket} gurur duyuyor! 🇹🇷💪": "{memleket} est fier ! 💪",
  "Az önce {p} maçını izledim, tüylerim diken diken.": "Je viens de voir le combat de {p}, j'ai la chair de poule.",
  "Bir sonraki maçına bilet alıyorum, kimse beni durduramaz.": "J'achète des billets pour le prochain combat, rien ne m'arrêtera.",
  "Oyun planı felaketti. Hoca değişmeli.": "Le plan de match était une catastrophe. L'entraîneur doit partir.",
  "Kötü gün herkesin başına gelir. {p} döner.": "Tout le monde a ses mauvais jours. {p} reviendra.",
  "Bu kadar hype’a bu performans mı? 🤡": "Tout ce battage pour cette performance ? 🤡",
  "{p} kampta tatil mi yaptı acaba?": "{p} a pris des vacances au lieu de faire un camp ?",
  "Kafam hâlâ inanmıyor ya… ❤️‍🩹": "Je n'arrive toujours pas à y croire… ❤️‍🩹",
  "{p} abartılıyormuş, belli oldu.": "Finalement, {p} était surcoté.",
  "Üzülme {p}, büyük şampiyonlar da kaybeder. Kalk ayağa! ❤️": "Ne sois pas triste, {p}, les grands champions perdent aussi. Relève-toi ! ❤️",
  "Kamp değişmeli. Bu oyun planı neydi?": "Le camp doit changer. C'était quoi ce plan de match ?",
  "Hâlâ arkandayız {p}. 💪": "On est toujours derrière toi, {p}. 💪",
  "HAHAHA efsane 😂🔥": "HAHAHA légendaire 😂🔥",
  "Bu adamın ağzı da yumrukları kadar sert!": "La bouche de ce combattant est aussi dure que ses poings !",
  "Gerilim tırmanıyor, bu maçı kaçırmam!": "La tension monte, je ne rate pas ce combat !",
  "Önce bir kemer al, sonra konuş.": "Gagne d'abord une ceinture, après tu parleras.",
  "Çok konuşan az dövüşür.": "Ceux qui parlent le plus combattent le moins.",
  "Bu biraz fazlaydı…": "C'était un peu too much…",
  "Saygılı sporcu = gerçek sporcu 👏": "Athlète respectueux = vrai athlète 👏",
  "Bu yüzden seviyoruz seni {p}.": "C'est pour ça qu'on t'aime, {p}.",
  "Klas bir hareket.": "Un geste classe.",
  "Kampa odaklan şampiyon!": "Concentre-toi sur le camp, champion !",
