  "🔥 İNTİKAM GECESİ: {0}, kendisini yenen {1} karşısında. İlk maç {2} lehine bitmişti. Bu sefer?": "🔥 SOIRÉE DE LA REVANCHE : {0} affronte {1}, celui qui l'a battu. Le premier combat est allé à {2}. Et cette fois ?",
  "🔁 RÖVANŞ: {0} ve {1} yeniden karşı karşıya. İlk maçın galibi {2}. Tarih tekerrür eder mi?": "🔁 REVANCHE : {0} et {1} se retrouvent. {2} a gagné le premier combat. L'histoire va-t-elle se répéter ?",
  "🏆 KEMER SAVAŞI: {0} şampiyonu {1}, tahtını yükselen isim {2}’ye karşı koruyor. 5 raunt, tek kemer.": "🏆 GUERRE DE LA CEINTURE : le champion {0} {1} défend son trône face au nom qui monte, {2}. 5 rounds, une ceinture.",
  "🏆 UNVAN SAVUNMASI: Şampiyon {0}, aç kurt {1} karşısında. Kemer el değiştirir mi?": "🏆 DÉFENSE DU TITRE : le champion {0} affronte le loup affamé {1}. La ceinture va-t-elle changer de mains ?",
  "📈 YENİLMEZLİK SERİSİ: {0} {1} maçtır kaybetmiyor. {2} bu seriyi bitirecek kişi olabilir mi?": "📈 SÉRIE D'INVINCIBILITÉ : {0} n'a pas perdu depuis {1} combats. {2} sera-t-il celui qui y mettra fin ?",
  "⚔️ STİL SAVAŞI: {0} ustası {1} vs {2} uzmanı {3}. Vuruşçu mu kazanır, güreşçi mi?": "⚔️ CHOC DES STYLES : le maître du {0} {1} contre le spécialiste du {2} {3}. Striker ou grappler ?",
  "🎤 SÖZ SAVAŞI: {0} haftalardır {1} hakkında konuşuyor. Kafeste sözlerin bedeli ödenecek.": "🎤 GUERRE DES MOTS : {0} parle de {1} depuis des semaines. Dans la cage, les mots ont un prix.",
  "📰 {0} bu hafta: {1} vs {2}. Bahisçiler {3} tarafını favori görüyor.": "📰 Cette semaine au {0} : {1} contre {2}. Les bookmakers donnent {3} favori.",
