  "Işıklar kararıyor. Spiker mikrofonu kaldırıyor, salon uğulduyor. Kafes kapısı kapanıyor ve hakem ikinizin arasına giriyor.": "Les lumières baissent. Le speaker lève le micro, la salle rugit. La porte de la cage se ferme et l'arbitre se place entre vous.",
