  "Amatör ligde resmi sıralama yok. Profesyonel olduğunda organizasyonunun sıklet sıralaması burada açılacak.": "Il n'y a pas de classement officiel en ligue amateur. Quand tu passeras pro, le classement de ta catégorie apparaîtra ici.",
  "Bu organizasyonda sıralama yok. Tek gecelik bir fırsat: kazanırsan kapılar açılır.": "Cette organisation n'a pas de classement. Une chance d'un soir : gagne et les portes s'ouvrent.",
  "Resmi sıralama · Bir dövüşçüye dokun, istatistiklerini gör": "Classement officiel · Touche un combattant pour voir ses stats",
  "GÜÇ": "PUISSANCE",
  "Henüz sıralamada değilsin. Galibiyetlerle listeye gir.": "Tu n'es pas encore classé. Entre dans la liste en gagnant.",
  "NE KADAR DİNLENECEKSİN?": "COMBIEN DE TEMPS VAS-TU TE REPOSER ?",
