  "Karakterini Nasıl Kurarsın?": "Comment construire ton personnage ?",
  "🌍 Uyruk: Antrenman imkânı başlangıç istatistiklerini, taraftar desteği başlangıç popülerliğini belirler. İlk salonun ve hocan da ülkene göre gelir.": "🌍 Nationalité : les options d'entraînement fixent tes stats de départ, le soutien des fans ta popularité de départ. Ta première salle et ton entraîneur dépendent aussi de ton pays.",
  "🎂 Yaş (18-30): Genç başlarsan ham ama hızlı gelişirsin (×1.3). Yaşlı başlarsan güçlü başlarsın ama 32’den sonra hız ve çene düşmeye başlar. 41’de emeklilik kaçınılmazdır.": "🎂 Âge (18-30) : en commençant jeune, tu es brut mais tu progresses vite (×1,3). En commençant plus vieux, tu es plus fort, mais après 32 ans la vitesse et le menton baissent. La retraite est inévitable à 41 ans.",
  "⚖️ Sıklet: Hafif sıkletler hızlı ve dayanıklıdır, ağır sıkletler sert vurur ama çabuk yorulur.": "⚖️ Catégorie : les catégories légères sont rapides et endurantes, les poids lourds frappent fort mais se fatiguent vite.",
  "🥋 Branş: En önemli seçim. Güçlü ve zayıf yönlerini, dolayısıyla nasıl dövüşeceğini belirler.": "🥋 Parcours : le choix le plus important. Il définit tes forces et tes faiblesses, donc ta façon de combattre.",
  "📖 Hikâye: Kendin yazabilir ya da oyuna yazdırabilirsin.": "📖 Histoire : écris-la toi-même ou laisse le jeu l'écrire.",
  "🎲 Zar: Son adımda istatistiklerin zarla belirlenir. Beğenmezsen 2 kez yeniden atabilirsin.": "🎲 Dés : à la dernière étape, tes stats sont tirées aux dés. Elles ne te plaisent pas ? Tu peux relancer deux fois.",
  "Gelişim Puanı": "Points de compétence",
  "Kariyere 3 puanla başlarsın. Her antrenman kampı 1-3 puan verir (yoğunluk, yaş, kamp yeri, hoca ve kadro kalitesine bağlı). Kampın odak alanı ayrıca +1-3 gelişir.": "Tu commences ta carrière avec 3 points. Chaque camp d'entraînement donne 1 à 3 points (selon l'intensité, l'âge, le lieu du camp, l'entraîneur et la qualité de l'équipe). Le domaine de focus du camp progresse aussi de +1 à 3.",
  "Dövüşler de puan verir: galibiyet 2, bitiriş +1, bonus +1, kemer +1. Mağlubiyet ve beraberlik 1 puan.": "Les combats donnent aussi des points : victoire 2, finition +1, bonus +1, ceinture +1. Défaite et match nul : 1 point.",
  "📅 Bir dövüş döngüsü (kamp + toparlanma) yaklaşık 90-100 gün sürer. Yılda 3-4 kez dövüşürsün; her karar önemli.": "📅 Un cycle de combat (camp + récupération) dure environ 90 à 100 jours. Tu combats 3 à 4 fois par an ; chaque décision compte.",
  "Puanı istediğin istatistiğe harcarsın. 50’ye kadar +1 için 1 puan, 70’e kadar 2, 85’e kadar 3, sonrası 4 puan gerekir.": "Dépense tes points sur la stat de ton choix. Jusqu'à 50, +1 coûte 1 point ; jusqu'à 70, 2 ; jusqu'à 85, 3 ; au-delà, 4 points.",
  "Kamp sonunda tartıdan önce, dövüş sonrasında ya da Kariyer ekranındaki GELİŞİM sekmesinden harcayabilirsin.": "Tu peux les dépenser avant la pesée en fin de camp, après un combat ou dans l'onglet PROGRESSION de l'écran de carrière.",
  "Nasıl Oynanır?": "Comment jouer",
  "1️⃣ Rakip seç. Bölgesel aşamada sen seçersin, büyük organizasyonlarda rakibi organizasyon dayatır.": "1️⃣ Choisis un adversaire. Au niveau régional, tu choisis ; dans les grandes organisations, l'adversaire t'est imposé.",
  "2️⃣ Kamp: odak alanı, oyun planı, yoğunluk, kilo verme ve basın toplantısı. Oyun planı rakibin zaafına denk gelirse kafeste büyük avantaj sağlar.": "2️⃣ Camp : domaine de focus, plan de match, intensité, coupe de poids et conférence de presse. Un plan de match qui vise le point faible de l'adversaire donne un gros avantage dans la cage.",
  "3️⃣ Dövüş: her raunt taktik seçersin. Kritik anlarda (rakip sarsıldı, submission yakalandı) hızlı karar verirsin.": "3️⃣ Combat : choisis une tactique à chaque round. Dans les moments critiques (adversaire ébranlé, soumission placée), tu prends des décisions rapides.",
  "4️⃣ Sonrası: bonuslar, röportaj, sıralama, kontrat teklifleri ve dövüşler arası olaylar.": "4️⃣ Après : bonus, interview, classement, offres de contrat et événements entre les combats.",
  "🏆 Yol: Amatör → Bölgesel (CFC, Hexagon) → Büyük (PFC, ZEN, VIP) → DWCS veya kısa haber → UCC kemeri.": "🏆 La route : Amateur → Régional (CFC, Hexagon) → Grandes organisations (PFC, ZEN, VIP) → DWCS ou préavis court → Ceinture UCC.",
  "BOŞ YUVA": "EMPLACEMENT VIDE",
  "Yeni bir kariyere başla": "Commencer une nouvelle carrière",
  " · SON OYNANAN": " · DERNIÈRE PARTIE",
  "EMEKLİ": "RETRAITÉ",
  "yaş ·": "ans ·",
  "Amatör ": "Amateur ",
