  "{0} sokaklarından çıktı, {1} yılda kemere uzandı. Sıradaki kim?": "Sorti des rues de {0}, il a décroché la ceinture en {1} ans. Au suivant ?",
  "{0} karşısında: {1}.": "Contre {0} : {1}.",
  "{0} sokaklarından çıktı; {1} yaşında {2} galibiyete ulaştı, {3} bitiriş.": "Sorti des rues de {0} ; à {1} ans, {2} victoires et {3} finitions.",
  "HOCAN · {0}": "TON ENTRAÎNEUR · {0}",
  "ANLADIM": "COMPRIS",
  "İpuçlarını kapat": "Désactiver les conseils",
  "Burası senin köşen": "C'est ton coin",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. Aradaki haftalarda mağaza, sosyal medya ve gece hayatı seni bekliyor; ama unutma, her şeyin bir bedeli var.": "En haut, ton argent, ta santé et ta popularité. Quand tu es prêt, choisis ton adversaire avec « ORGANISER UN COMBAT ». Entre les combats, la boutique, les réseaux et la vie nocturne t'attendent ; mais n'oublie pas, tout a un prix.",
  "Gelişim puanları": "Points de compétence",
  "Kamplardan ve dövüşlerden puan kazanırsın, burada istatistiklerine dağıtırsın. 50’den sonra her artış pahalanır; zayıf yönünü kapatmak çoğu zaman daha akıllıcadır.": "Tu gagnes des points avec les camps et les combats et tu les dépenses ici sur tes stats. Au-delà de 50, chaque point coûte plus cher ; combler ton point faible est souvent plus malin.",
  "Rakibini seç": "Choisis ton adversaire",
  "Her rakibin gücü ve zayıf yönü yazıyor. Kolay rakip güvenlidir ama az kazandırır; riskli bir rakibi yenersen sıralamada büyük bir sıçrama yaparsın.": "La puissance et le point faible de chaque adversaire sont indiqués. Un adversaire facile est sûr mais rapporte peu ; bats un adversaire risqué et tu feras un grand bond au classement.",
  "Kamp başlıyor": "Le camp commence",
  "Önce kampın süresini seç. Uzun kamp daha çok geliştirir ama pahalıdır ve yorar. Kamptan önceki boş haftalarda teknik çalışabilir, spar yapabilirsin.": "Choisis d'abord la durée de ton camp. Un camp long te fait plus progresser mais coûte plus cher et t'use davantage. Pendant les semaines libres avant le camp, tu peux travailler la technique et faire du sparring.",
  "Oyun planı": "Plan de match",
  "Rakibin zayıf yönüne uyan plan, dövüşte etkisini ikiye katlar. Keşif raporuna bak ve planını ona göre seç.": "Un plan qui correspond au point faible de ton adversaire double son effet en combat. Consulte le rapport de scouting et choisis ton plan en conséquence.",
  "Burun buruna": "Face à face",
  "Tartıdan sonra rakibinle yüz yüze geleceksin. Takındığın tavır onun moralini bozabilir ya da sana pahalıya patlayabilir.": "Après la pesée, tu te retrouveras face à ton adversaire. Ton attitude peut briser son moral ou te coûter cher.",
  "Her raundun başında bir taktik seç, dövüş kendi akar. Rakip sarsıldığında ya da bir submission fırsatında hızlı karar vermen gerekir. Kondisyonunu izle: yorulursan her şey zorlaşır.": "Choisis une tactique au début de chaque round et le combat se déroule tout seul. Quand ton adversaire vacille ou qu'une soumission s'offre à toi, il faudra décider vite. Surveille ton cardio : une fois fatigué, tout devient plus dur.",
  "Dövüş bitti": "Le combat est terminé",
  "Mikrofon sende: röportajdaki sözlerin popülerliğini etkiler. Kazandığın puanları GELİŞİM sekmesinde harca. Güzel bir galibiyet mi? Paylaş, herkes görsün!": "Le micro est à toi : ce que tu dis en interview influence ta popularité. Dépense les points gagnés dans l'onglet PROGRESSION. Une belle victoire ? Partage-la pour que tout le monde la voie !",
  "Google Play’de ücretsiz": "Gratuit sur Google Play",
