  "HIZLI BAŞLA": "DÉMARRAGE RAPIDE",
  "Kalan adımları biz seçelim: branş, sıklet, görünüm ve hikâye. Hemen salona gir, her şeyi sonradan oynarken öğrenirsin.": "On choisit le reste pour toi : discipline, catégorie, apparence et histoire. Va directement à la salle et apprends en jouant.",
  "Hemen başla": "Commencer maintenant",
  "ya da DEVAM ile karakterini adım adım kendin kur": "ou touche CONTINUER pour créer ton combattant étape par étape",
  "🏁 Rekabet bitti! {0} sonunda kabul etti: \"Sen daha iyiydin, {1}.\" Aranızdaki seri: {2}. Popülerlik +5.": "🏁 La rivalité est terminée ! {0} l'a enfin admis : « Tu étais meilleur, {1}. » Bilan : {2}. Popularité +5.",
  "Bugün kafeste daha iyi olan kazandı. Saygılar {0}. Bu rekabet beni daha iyi bir dövüşçü yaptı.": "Le meilleur combattant a gagné ce soir. Respect, {0}. Cette rivalité a fait de moi un meilleur combattant.",
  "🏁 {0} emekliliğini açıkladı: \"Kariyerimdeki en zor rakip sendin, {1}.\" Seriyi sen kazandın: {2}.": "🏁 {0} a annoncé sa retraite : « Tu as été l'adversaire le plus dur de ma carrière, {1}. » Tu as remporté le bilan : {2}.",
  "🏁 {0} emekliliğini açıkladı. Aranızdaki seri: {1}. Onu hiç tam geçemedin; bu hikâye böyle bitti.": "🏁 {0} a annoncé sa retraite. Bilan : {1}. Tu n'as jamais vraiment pris le dessus ; c'est ainsi que se termine cette histoire.",
  "⚔️ Ezeli rakibin {0} karşısında kazandın! Aranızdaki seri: {1}.": "⚔️ Tu as battu ton ennemi juré {0} ! Bilan : {1}.",
  "Bu gece senin gecendi. Ama bu iş bitmedi, {0}.": "Ce soir, c'était ta soirée. Mais ce n'est pas fini, {0}.",
  "Rövanş istiyorum. Organizasyon duysun!": "Je veux la revanche. Vous entendez, l'organisation ?",
  "Şans bir kez güler. Üçüncü maçta görüşürüz.": "La chance ne sourit qu'une fois. À la prochaine.",
  "⚔️ Ezeli rakibinle berabere. Aranızdaki seri: {0}. Kimse tatmin olmadı.": "⚔️ Match nul contre ton ennemi juré. Bilan : {0}. Personne n'est satisfait.",
  "⚔️ {0} yine kazandı. Aranızdaki seri: {1}. Bu iş bitmedi.": "⚔️ {0} a encore gagné. Bilan : {1}. Ce n'est pas fini.",
  "Söylemiştim. Kafeste ne zaman karşılaşsak aynı son. 😏": "Je te l'avais dit. Chaque fois qu'on se croise dans la cage, même fin. 😏",
  "{0}, bir daha karşıma çıkmadan önce iki kere düşün.": "{0}, réfléchis à deux fois avant de m'affronter à nouveau.",
  "Kral benim. Anlaşıldı mı?": "C'est moi le roi. Compris ?",
  "🗡️ {0} maçtan sonra mikrofonu aldı: \"Bu daha başlangıç. Kafeste her karşılaştığımızda aynı sonuç olacak.\" Bu isim peşini kolay bırakmayacak: artık bir ezeli rakibin var.": "🗡️ {0} a pris le micro après le combat : « Ce n'est que le début. Chaque fois qu'on se croisera dans la cage, ça finira pareil. » Ce nom ne lâchera pas facilement : tu as maintenant un ennemi juré.",
  "{0} iyi dövüşçü ama bana göre değil. Ne zaman isterse tekrar.": "{0} est un bon combattant, mais pas à mon niveau. Quand il veut pour une revanche.",
  "🗡️ {0} kameralara konuştu: \"{1} yenilmez sanılıyor. O balonu ben patlatacağım.\" Yeni bir ezeli rakibin var.": "🗡️ {0} a déclaré face aux caméras : « Tout le monde pense que {1} est imbattable. Je vais faire éclater cette bulle. » Tu as un nouvel ennemi juré.",
  "{0}, kaçamazsın. Sıra bende.": "{0}, tu ne peux pas fuir. Je suis le prochain.",
  "{1} karşısında kazanmak mı? Onu ben de yenerdim. Asıl sınav benim, {0}.": "Battre {1} ? Je l'aurais battu aussi. C'est moi le vrai test, {0}.",
  "Herkes seni konuşuyor {0}. Ben hâlâ o geceyi hatırlıyorum. 😏": "Tout le monde parle de toi, {0}. Moi, je me souviens encore de cette nuit-là. 😏",
  "Güzel galibiyet {0}. Ama bir gün yine karşılaşacağız.": "Belle victoire, {0}. Mais on se retrouvera un jour.",
  "{0} formda görünüyor. Ben de. Tarih verin.": "{0} a l'air affûté. Moi aussi. Fixe la date.",
  "{1} bile seni yendi. Ben sana söylemiştim, {0}.": "Même {1} t'a battu. Je te l'avais dit, {0}.",
  "Kafeste yerin yok, {0}. Bunu en iyi ben biliyorum.": "Ta place n'est pas dans la cage, {0}. Personne ne le sait mieux que moi.",
