  "Mahkeme senden yana karar verdi: {0} geri geldi. Hikâyen herkese örnek oldu. Popülerlik +2.": "Le tribunal t'a donné raison : {0} récupérés. Ton histoire est devenue un exemple pour tous. Popularité +2.",
