  "Affettin. Menajerin minnettar ama ekipte bir şey kırıldı. Motivasyon -1.": "Tu as pardonné. Ton manager t'en est reconnaissant, mais quelque chose s'est brisé dans l'équipe. Motivation -1.",
  "🥊 Babanın Hayali": "🥊 Le rêve de ton père",
  "Baban gençliğinde amatör boksörmüş. Şimdi 58 yaşında, bir yardım gecesinde son bir kez ringe çıkmak istiyor. Senden destek bekliyor.": "Ton père était boxeur amateur dans sa jeunesse. Il a 58 ans et veut monter une dernière fois sur le ring lors d'une soirée caritative. Il compte sur ton soutien.",
  "Destekle, onu çalıştır": "Le soutenir, l'entraîner",
  "Vazgeçirmeye çalış": "Essayer de l'en dissuader",
  "Sabah koşularına artık baban da geliyor. Salonda herkes ona “Usta” diyor. Motivasyon +1.": "Ton père t'accompagne maintenant pour les footings du matin. À la salle, tout le monde l'appelle « Maître ». Motivation +1.",
  "Ona riskleri anlattın. Sessizce dinledi, bir şey demedi.": "Tu lui as expliqué les risques. Il a écouté en silence sans rien dire.",
  "💔 Kırgın Bir Baba": "💔 Un père blessé",
  "Baban yardım gecesine çıkmadı ama sana kırgın: “Sen kendi yolunu seçtin, ben de bir kez seçmek istemiştim.”": "Ton père n'a pas combattu à la soirée caritative, mais il est blessé : « Tu as choisi ton chemin. Je voulais choisir le mien, juste une fois. »",
  "Özür dile, onu bir sonraki maçına davet et": "T'excuser et l'inviter à ton prochain combat",
  "Zamanla geçer": "Ça passera avec le temps",
  "🎉 Babanın Gecesi": "🎉 La soirée de ton père",
  "Baban üç raunt boyunca dimdik durdu ve salon ayağa kalktı! Onu ringte kucakladığın video her yerde.": "Ton père a tenu trois rounds et toute la salle s'est levée ! La vidéo où tu l'enlaces sur le ring est partout.",
  "Onunla gurur duy": "Être fier de lui",
  "🏥 Zor Bir Gece": "🏥 Une nuit difficile",
  "Baban ikinci rauntta düştü. İyi, ama bir gece hastanede kalacak. Masraflar {0}.": "Ton père est tombé au deuxième round. Il va bien, mais il passera une nuit à l'hôpital. Les frais s'élèvent à {0}.",
  "Yanında ol": "Rester à ses côtés",
  "Maç gecesi baban ilk sıradaydı. Aranızdaki buz eridi. Motivasyon +1.": "Le soir du combat, ton père était au premier rang. La glace entre vous a fondu. Motivation +1.",
  "Aranızdaki mesafe büyüdü. Motivasyon -1.": "La distance entre vous s'est creusée. Motivation -1.",
  "Baba-evlat hikâyesi herkesin yüreğine dokundu. Popülerlik +4, motivasyon +1.": "L'histoire du père et de son enfant a touché tout le monde. Popularité +4, motivation +1.",
  "Sabaha kadar yanındaydın. Taburcu olurken gülümsedi: “Değdi.” Motivasyon +1.": "Tu es resté avec lui jusqu'au matin. À sa sortie, il a souri : « Ça valait le coup. » Motivation +1.",
  "YOL: Kafesten Kemere · {0} {1} kariyer kodu (Menü → Kariyer içe aktar):": "YOL : De la cage à la ceinture · code de carrière de {0} {1} (Menu → Importer une carrière) :",
  "Kariyer kodu kopyalandı. Yeni cihazda Menü → Kariyer içe aktar.": "Code de carrière copié. Sur le nouvel appareil : Menu → Importer une carrière.",
  "Kariyeri dışa aktar": "Exporter la carrière",
  "Kod okunamadı. Tamamını kopyaladığından emin ol.": "Impossible de lire le code. Vérifie que tu l'as copié en entier.",
  "Boş yuva yok. Önce bir kariyeri sil ya da yuvaları artır.": "Aucun emplacement libre. Supprime d'abord une carrière ou débloque plus d'emplacements.",
  "Kariyer içe aktar": "Importer une carrière",
  "KARİYERİ TAŞI": "TRANSFÉRER UNE CARRIÈRE",
  "Eski cihazında yuvanın yanındaki dışa aktar düğmesiyle kariyer kodunu al, buraya yapıştır. Kariyer ilk boş yuvaya eklenir.": "Sur ton ancien appareil, récupère le code de carrière avec le bouton d'export à côté de l'emplacement et colle-le ici. La carrière ira dans le premier emplacement libre.",
