  "Bir şeyler ters gitti": "Un problème est survenu",
  "Bu ekran açılırken bir hata oluştu. Kariyerin güvende: menüye dönüp devam edebilirsin. Sorun sürerse son sağlam kayda dön.": "Une erreur s'est produite à l'ouverture de cet écran. Ta carrière est en sécurité : retourne au menu et continue. Si le problème persiste, reviens à la dernière sauvegarde valide.",
