  "İpucu: Hakarete espriyle, övünmeye sert, alaya soğukkanlı cevap ver.": "Astuce : réponds aux insultes avec humour, à la vantardise avec du feu, à la moquerie avec de la glace.",
  "{0} mi? Bu kafese değil, kreşe gitmeli.": "{0} ? Celui-là, c'est la crèche, pas la cage.",
  "Şu surata bakın: daha önce çok dayak yediği belli.": "Regardez-moi cette tête. On voit qu'elle a pris pas mal de coups.",
  "Onun antrenmanlarını izledim. Annem daha sert vuruyor.": "J'ai vu les vidéos d'entraînement. Ma mère frappe plus fort.",
  "Tek yeteneği basın toplantısında uyumamak.": "Le seul talent ici, c'est de rester éveillé en conférence de presse.",
  "Ben bu sıkletin kralıyım. Onu ilk rauntta uyutacağım, yazın bir kenara.": "Je suis le roi de cette catégorie. Extinction des feux au premier round, note-le.",
  "Bana rakip bulamıyorlar, o yüzden bunu getirdiler.": "Ils ne trouvent pas de vrais adversaires pour moi, alors ils ont amené ça.",
  "Kemeri şimdiden evime astım. Bu maç sadece formalite.": "La ceinture est déjà accrochée chez moi. Ce combat est une formalité.",
  "Benim ısınmam onun bütün kariyeri kadar sürüyor.": "Mon échauffement dure plus longtemps que toute cette carrière.",
  "Hahaha! {0} titriyor bakın, ellerine bakın!": "Hahaha ! {0} tremble, regardez ces mains !",
  "Kilo verirken ağladığını duydum. Çok tatlı.": "Il paraît qu'il y a eu des larmes pendant la coupe de poids. Trop mignon.",
  "Gözlerime bakamıyor bile. Daha şimdiden kaybetti.": "Pas capable de me regarder dans les yeux. Déjà perdu.",
  "Hocası bile onun yerine utanıyor, şu hâline bakın.": "Même l'entraîneur a honte. Regardez-moi ça.",
  "Kreş mi? Doğru, cumartesi seni orada bebek gibi uyutacağım.": "La crèche ? D'accord, samedi je t'endors comme un bébé.",
  "Annenle antrenman yapıyorsan bana da numarasını ver, belki bir şey öğrenirim.": "Si tu t'entraînes avec ta mère, donne-moi son numéro. J'apprendrai peut-être quelque chose.",
  "Konuş, konuş. Cumartesi gecesi konuşamayacaksın.": "Continue de parler. Samedi soir, tu ne pourras plus.",
  "Laflar ucuz. Kafeste görüşürüz.": "Les paroles ne coûtent rien. Rendez-vous dans la cage.",
  "Bir daha ağzını açarsan burada dağıtırım seni!": "Ouvre encore la bouche et je te démolis ici même !",
  "Kapa çeneni yoksa ben kapatırım!": "Ferme-la ou je te la ferme !",
  "Kral mı? Son üç maçında yere kaç kez düştüğünü sayalım mı?": "Roi ? On compte combien de fois tu as touché le sol lors de tes trois derniers combats ?",
  "Kemeri evine asmışsın, güzel. Ben gelip alacağım.": "La ceinture est sur ton mur ? Parfait. Je viendrai la prendre.",
  "İlk rauntta uyutacakmış… herhalde bu konuşmasıyla.": "Extinction des feux au premier round… avec ce discours, peut-être.",
  "Tamam. Görürüz.": "D'accord. On verra.",
  "Saygı duyuyorum, iyi şanslar.": "Je respecte ça. Bonne chance.",
  "Gülmeye devam et. Son gülen iyi güler.": "Continue de rire. Rira bien qui rira le dernier.",
  "Ellerim titremiyor, sadece seni beklemekten sıkıldılar.": "Mes mains ne tremblent pas. Elles s'ennuient juste à t'attendre.",
  "Gülüyor musun? Cumartesi gülemeyeceksin!": "Tu rigoles ? Samedi, tu ne rigoleras plus !",
  "Bir daha bana gülersen sahnede kavga çıkar!": "Moque-toi encore de moi et ça va se battre sur cette scène !",
  "Hahaha, evet çok komiksin… dur, bunu anneme de anlatayım.": "Hahaha, ouais, t'es hilarant… attends, je vais le dire à ma mère.",
  "Titriyorum çünkü burası çok soğuk, senin kariyerin gibi.": "Je tremble parce qu'il fait froid ici, comme ta carrière.",
