  "🎤 Basın toplantısında laflar havada uçuştu, kimse üstün gelemedi. Popülerlik +2. {0} gaza geldi.": "🎤 Les mots ont fusé en conférence de presse, mais personne n'a gagné. Popularité +2. {0} est remonté.",
  "🎤 Basın toplantısını sen kazandın! Video milyonlarca izlendi. {0}. {1} sinirden ne dediğini bilmiyordu (rakip IQ -2).": "🎤 Tu as gagné la conférence de presse ! L'extrait a fait des millions de vues. {0}. {1} était si déstabilisé qu'il n'arrivait plus à réfléchir (QI adverse -2).",
  "Basın toplantısında rakiple canlı laf düellosuna gir. Kazanırsan popülerlik patlar, kaybedersen alay konusu olursun.": "Affrontez-vous en direct dans un duel de trash-talk en conférence de presse. Gagne et ta popularité explose ; perds et tu deviens un mème.",
