  "{0} Kartalları": "Aigles de {0}",
  "📣 Resmi taraftar kulübümüz kuruldu! {0} için tribünlerdeyiz. 💪": "📣 Notre fan-club officiel est fondé ! On est dans les tribunes pour {0}. 💪",
  "📣 {0} kuruldu! {1} kurucu üye.": "📣 {0} est fondé ! {1} membres fondateurs.",
  "Kulüp gecesi düzenle": "Organiser une soirée du club",
  "Yemek, fotoğraf, imza. Sadakat +8, üye artışı.": "Dîner, photos, autographes. Fidélité +8, nouveaux membres.",
  "Açık antrenman": "Entraînement ouvert",
  "Taraftarlar salonda seni izler. 1 hafta sürer. Sadakat +5.": "Les fans te regardent t'entraîner à la salle. Prend 1 semaine. Fidélité +5.",
  "İmzalı eldiven çekilişi": "Tirage au sort de gants signés",
  "Sosyal medyada patlar. Büyük üye artışı, sadakat +3.": "Ça explose sur les réseaux. Gros afflux de membres, fidélité +3.",
