  "Halka altın olunca KAÇ, sonra hemen vur. DİREKT ve TEKME saldırı hazırlığını keser.": "Quand l'anneau devient doré, ESQUIVE, puis frappe tout de suite. DIRECT et COUP DE PIED interrompent un armé.",
  "📊 İsabet: {0} – {1} · Verilen hasar: {2} – {3}": "📊 Coups portés : {0} – {1} · Dégâts infligés : {2} – {3}",
