  "🔒 ya da ⤴️ görünce KONTROL. Rakip yorulunca SUB dene.": "Tu vois 🔒 ou ⤴️ ? Appuie sur CONTRÔLE. Tente la SOUM. quand il est fatigué.",
  "🔒 görünce hemen KURTUL. 👊 gelirken GARD al.": "Tu vois 🔒 ? ÉCHAPPE-TOI tout de suite. GARDE haute quand 👊 arrive.",
  "Halka altın olunca KAÇ (⬇️ takedown'a karşı da). DİREKT ve TEKME hazırlığı keser.": "Quand l'anneau devient doré, ESQUIVE (ça marche aussi contre les amenées ⬇️). DIRECT et COUP DE PIED interrompent un armé.",
  "🤼 Yerde kontrol: {0} sn – {1} sn": "🤼 Contrôle au sol : {0} s – {1} s",
  "🔒 TAP! {0} kilidin içinde tap attı. Submission!": "🔒 IL TAPE ! {0} a tapé dans la prise. Soumission !",
  "🔒 Kilitten çıkamadın… tap attın.": "🔒 Tu n'as pas pu sortir de la prise… tu as tapé.",
