  "Suplex": "Suplex",
  "Guard çek + kilit": "Tirage de garde + prise",
  "Savurma yumruk": "Coup de massue",
  "Rakibi oku": "Lis ton adversaire",
  "Rakip saldırı hazırlarken başında küçülen bir halka çıkar. Halka ALTIN olunca KAÇ'a bas, sonra hemen vur: kontra vuruşların çift hasar yapar.": "Quand ton adversaire arme son coup, un anneau qui rétrécit apparaît autour de sa tête. Quand l'anneau devient DORÉ, appuie sur ESQUIVE, puis frappe tout de suite : les contres font double dégât.",
  "Vur ve kes": "Frapper et interrompre",
  "JAB hızlı ve ucuz, DİREKT ve TEKME ağırdır. Rakip hazırlanırken DİREKT ya da TEKME atarsan saldırısını kesersin. Sarı çubuk nefesin: bitince vuruşların zayıflar.": "Le JAB est rapide et peu coûteux, le DIRECT et le COUP DE PIED sont lourds. Lance un DIRECT ou un COUP DE PIED pendant son armé pour l'interrompre. La barre jaune est ton énergie : quand elle est vide, tes coups faiblissent.",
  "İNDİR ile takedown dene; rakip ⬇️ ile dalarsa KAÇ ile sprawl yap. Yerde düğmeler değişir: üstteyken vur ve submission ara, alttayken 🔒 görünce hemen KURTUL.": "Tente une AMENÉE ; s'il attaque avec ⬇️, sprawle avec ESQUIVE. Au sol, les boutons changent : au-dessus, frappe et cherche la soumission ; en dessous, ÉCHAPPE-TOI dès que tu vois 🔒.",
  "DURAKLATILDI": "EN PAUSE",
