  "Takipçi para ve sponsor getirir.": "Les abonnés rapportent de l'argent et des sponsors.",
  "Amatörde 3 galibiyet al, teklifler gelsin.": "Gagne 3 combats amateurs et les offres arriveront.",
  "✅ {0}: +${1}, {2} takipçi.": "✅ {0} : +{1} $, {2} abonnés.",
  "İLK ADIMLAR": "PREMIERS PAS",
  "Üstte paran, sağlığın ve popülerliğin var. Hazır olduğunda “DÖVÜŞ AYARLA” ile rakibini seç. “İlk adımlar” sana yol gösterecek; maç yaptıkça yeni şeyler açılacak. Ama unutma, her şeyin bir bedeli var.": "En haut, tu vois ton argent, ta santé et ta popularité. Quand tu es prêt, choisis ton adversaire avec « ORGANISER UN COMBAT ». « Premiers pas » te guidera ; d'autres choses se débloquent au fil des combats. Mais souviens-toi : tout a un prix.",
