  "DİREN! Bas ve basılı tut": "RÉSISTE ! Appuie et maintiens",
  "Bas ya da basılı tut. DİREN! yanınca yeniden bas ve bırakma!": "Touche ou maintiens. Quand RÉSISTE ! s'allume, appuie à nouveau et ne lâche pas !",
  "Çubuk dolarsa tap atarsın! Bas ya da basılı tut, kurtul!": "Si la barre se remplit, tu tapes ! Touche ou maintiens pour t'échapper !",
  "DİREN!": "RÉSISTE !",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Bu organizasyonda hidrasyon testi var: kendini kurutma.": "⚖️ Tu feras ta propre coupe de poids dans les 48 dernières heures avant la pesée. Cette organisation fait un test d'hydratation : ne te dessèche pas.",
  "⚖️ Kilonu tartıdan önceki son 48 saatte kendin vereceksin. Su kesimini iyi yönetirsen kafese rakibinden iri çıkarsın.": "⚖️ Tu feras ta propre coupe de poids dans les 48 dernières heures avant la pesée. Gère bien la coupe hydrique et tu entreras plus gros que ton adversaire.",
  "Son 48 saat: kilonu ver": "48 dernières heures : faire le poids",
  "🏆 Yükseliş Grand Prix'i daveti geldi! 8 amatör, tek kupa: şampiyon ve finalist profesyonel kapıyı açar.": "🏆 Invitation au Grand Prix des espoirs ! 8 amateurs, un trophée : le champion et le finaliste ouvrent la porte du pro.",
  "🏆 Yükseliş Grand Prix'ine katıldın: 8 amatör, üç maç. Profesyonel organizasyonlar izliyor.": "🏆 Tu es entré dans le Grand Prix des espoirs : 8 amateurs, trois combats. Les organisations pro regardent.",
  "Yükseliş Grand Prix'i Şampiyonu ({0})": "Champion du Grand Prix des espoirs ({0})",
  "🏆 Yükseliş Grand Prix'ini kazandın! Organizasyonlar sıraya girdi: profesyonel kapı ardına kadar açık.": "🏆 Tu as gagné le Grand Prix des espoirs ! Les organisations font la queue : la porte du pro est grande ouverte.",
  "🥈 Finalde kaybettin ama herkes seni izledi. Profesyonel organizasyonlar seni kadrosunda istiyor!": "🥈 Tu as perdu la finale, mais tout le monde regardait. Les organisations pro te veulent dans leur effectif !",
  "YÜKSELİŞ GRAND PRIX'İ DAVETİ": "INVITATION AU GRAND PRIX DES ESPOIRS",
  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Ta vitrine sur la route du pro : 8 amateurs, trois combats (quart, demie, finale). Une défaite et tu es éliminé. Le champion remporte {0} et le trophée ; le champion et le finaliste reçoivent directement des offres pro. Cette invitation ne vient qu'une fois.",
