  "Şimşek desenli buz şortu, buz eldiveni, Buz Kralı çerçevesi ve kemeri, kafese KAR FIRTINASI ile giriş": "Short de glace à motif éclairs, gants de glace, cadre et ceinture Roi de glace, entrée dans un BLIZZARD",
