  "Tam Sürüm tek seferlik: reklamlar kalkar, ödüller anında gelir, 5 kariyer yuvası ve Altın Seri.": "Version complète, achat unique : sans pubs, récompenses instantanées, 5 emplacements de carrière et la Série Or.",
