  "🤝 {0} ile aranız çok iyi: köşedeki her sözü tam zamanında geliyor (IQ +1).": "🤝 Toi et {0} êtes en phase : chaque mot du coin tombe pile au bon moment (QI +1).",
  "🧊 {0} ile aranız soğuk: köşede konuşmalar kısa ve gergin (IQ -1).": "🧊 C'est froid avec {0} : les échanges dans le coin sont brefs et tendus (QI -1).",
  "{0}: “Seninle gurur duyuyorum. Şimdi git ve al şunu.”": "{0} : « Je suis fier de toi. Maintenant, va la chercher. »",
  "{0} yalnızca “Planı biliyorsun.” dedi. Sesi soğuktu.": "{0} a juste dit : « Tu connais le plan. » Sa voix était froide.",
  "💢 Hocanla Kriz": "💢 Crise avec ton entraîneur",
  "{0} antrenmandan sonra seni kenara çekti: “Beni dinlemiyorsun. Böyle devam edeceksek yollarımızı ayıralım.”": "Après l'entraînement, {0} t'a pris à part : « Tu ne m'écoutes pas. Si ça continue, on devrait se séparer. »",
