  "Gururunu yuttun. {0} başını salladı: “Yarın sabah altıda.” Bağ toparlanıyor, motivasyon -1.": "Tu as ravalé ta fierté. {0} a hoché la tête : « Demain, six heures. » Le lien se répare, motivation -1.",
  "Zam iyi geldi ama asıl önemli olan oturup konuşmanızdı. Bağ güçlendi.": "L'augmentation a aidé, mais ce qui a vraiment compté, c'est de vous parler. Le lien est plus fort.",
  "{0} ile yollarınız ayrıldı. Yeni hocan {1}. Sıfırdan bir güven kurmanız gerekecek. Motivasyon -1.": "Toi et {0}, c'est fini. Ton nouvel entraîneur est {1}. Il faudra reconstruire la confiance de zéro. Motivation -1.",
  "🫂 Bir Baba Gibi": "🫂 Comme un père",
  "Gece salonda yalnız kaldınız. {0} eski bir fotoğraf çıkardı: ilk antrenmanın, eldivenler elinden büyük. “O gün kapıdan girdiğinde ne olacağını biliyordum,” dedi.": "Tard le soir, seuls à la salle, {0} a sorti une vieille photo : ta première séance, des gants plus gros que tes mains. « Le jour où tu as passé cette porte, j'ai su », a-t-il dit.",
  "Sarıl": "Le prendre dans tes bras",
  "“Her şeyi sana borçluyum.”": "« Je te dois tout. »",
  "{0} ile ilk antrenman fotoğrafı": "Photo de la première séance avec {0}",
  "Eldivenler elinden büyük. Arkasında hocanın el yazısı: “Bir gün.”": "Des gants plus gros que tes mains. Au dos, de l'écriture de ton entraîneur : « Un jour. »",
  "Uzun süre konuşmadınız. Gerek yoktu. Motivasyon +2.": "Aucun de vous n'a parlé pendant longtemps. Pas besoin. Motivation +2.",
  "“Hayır,” dedi, “her şeyi kendine borçlusun. Ben sadece kapıyı açtım.” Motivasyon +2.": "« Non, a-t-il dit, tu ne dois tout qu'à toi-même. J'ai juste ouvert la porte. » Motivation +2.",
  "📨 Rakip Kampın Teklifi": "📨 L'offre d'un camp rival",
  "Büyük bir salon {0} hocana baş antrenörlük teklif etmiş, maaşı iki katı. Sana söylemedi; sen başkasından duydun.": "Une grande salle a proposé à ton entraîneur {0} un poste d'entraîneur principal pour le double du salaire. Il ne t'a rien dit ; tu l'as appris par quelqu'un d'autre.",
  "Ona zam yap ve kalmasını iste ({0})": "L'augmenter et lui demander de rester ({0})",
  "Onu tebrik et, gitmesine izin ver": "Le féliciter et le laisser partir",
  "Sessiz kal, kararı ona bırak": "Te taire, lui laisser le choix",
  "{0} teklifi reddetti: “Benim dövüşçüm burada.” Bağ çok güçlendi.": "{0} a refusé : « Mon combattant est ici. » Le lien est bien plus fort.",
  "{0} gözleri dolu gitti, giderken seni yeni hocan {1} ile tanıştırdı. Motivasyon +1.": "{0} est parti les larmes aux yeux, en te présentant ton nouvel entraîneur {1} au passage. Motivation +1.",
  "{0} kaldı. “Sana sormadan karar vermem gerekirdi, ama burası benim evim,” dedi.": "{0} est resté. « J'aurais dû décider sans te demander, mais c'est ma maison ici », a-t-il dit.",
  "{0} teklifi kabul etti. Yeni hocan {1}.": "{0} a accepté l'offre. Ton nouvel entraîneur est {1}.",
  "🏥 Hocanın Sağlığı": "🏥 La santé de ton entraîneur",
  "{0} birkaç haftadır öksürüyordu. Doktorlar dinlenmesini söyledi ama o kampı bırakmak istemiyor.": "{0} tousse depuis des semaines. Les médecins lui ont dit de se reposer, mais il refuse de quitter le camp.",
  "Zorla tatile gönder, kampı asistan yönetsin": "L'obliger à se reposer ; l'assistant dirige le camp",
  "Onun kararına saygı duy": "Respecter sa décision",
  "Önce kızdı, sonra teşekkür etti. Bir ay sonra eskisinden dinç döndü. Bağ güçlendi.": "Il était en colère au début, puis reconnaissant. Un mois plus tard, il est revenu plus fort que jamais. Le lien a grandi.",
  "Kampı yönetti ama her gece onu merak ettin. Motivasyon -1.": "Il a dirigé le camp, mais tu t'es inquiété pour lui chaque nuit. Motivation -1.",
  "🕊️ Hocanın Vedası": "🕊️ Les adieux de ton entraîneur",
  "{0} seni salonun ortasına çağırdı: “Yaşlandım evlat. Sana öğretebileceğim her şeyi öğrettim.” Yerine kendi asistanını önerdi.": "{0} t'a appelé au milieu de la salle : « Je me fais vieux, petit. Je t'ai appris tout ce que je pouvais. » Il a proposé que son assistant prenne le relais.",
  "Son bir antrenman yapın": "Faire une dernière séance",
  "Veda yemeği düzenle": "Organiser un dîner d'adieu",
  "{0} ile son fotoğraf": "Dernière photo avec {0}",
  "Son antrenmanın sonunda minderde yan yana": "Côte à côte sur le tapis après la dernière séance",
  "Veda yemeğinde, bütün salon bir arada": "Au dîner d'adieu, toute la salle réunie",
  "Asistan {0}": "Assistant {0}",
  "Emre": "Emre",
