  "{0} emekli oldu ama her maçını tribünden izleyeceğine söz verdi. Yeni hocan {1}. Motivasyon +1.": "{0} a pris sa retraite mais a promis de regarder chaque combat depuis les tribunes. Ton nouvel entraîneur est {1}. Motivation +1.",
