  "🎬 Film Teklifi": "🎬 Offre de film",
  "Bir yapımcı seni “{0}” adlı aksiyon filminde kötü adam olarak istiyor. Çekimler üç hafta, Hollywood'dan bir yönetmen.": "Un producteur te veut comme méchant dans le film d'action « {0} ». Trois semaines de tournage, un réalisateur hollywoodien.",
  "Sette herkes senden korktu, sonra sevdi. Fragman bir günde 20 milyon izlendi.": "Sur le plateau, tout le monde te craignait, puis t'a adoré. La bande-annonce a fait 20 millions de vues en un jour.",
  "🎥 Belgesel Teklifi": "🎥 Offre de documentaire",
  "Bir yayın platformu senin hayatını anlatan bir belgesel çekmek istiyor. Kamera ekibi bir sonraki kampın boyunca peşinde olacak; memleketine, ailene de gidecekler.": "Une plateforme de streaming veut faire un documentaire sur ta vie. Une équipe te suivra pendant ton prochain camp et ira voir ta ville natale et ta famille.",
  "Kafesten Kemere": "De la cage à la ceinture",
  "Kamera her şeyi çekti: sabah koşularını, kesimin zor anlarını, annenin mutfağını. İzleyiciler seni tanıdı.": "La caméra a tout capté : les footings du matin, les moments durs de la coupe de poids, la cuisine de ta mère. Les spectateurs ont appris à te connaître.",
  "📺 Reklam Yüzü": "📺 Visage d'une campagne",
  "{0} yeni kampanyasının yüzü olmanı istiyor. Bir günlük çekim, ülke çapında billboard.": "{0} te veut comme visage de sa nouvelle campagne. Une journée de tournage, des affiches dans tout le pays.",
  "Şehrin her köşesinde yüzün var. Annen her billboard'un fotoğrafını çekiyor.": "Ton visage est à chaque coin de rue. Ta mère photographie chaque affiche.",
  "🎙️ Talk Show Daveti": "🎙️ Invitation dans un talk-show",
  "“{0}” programı seni konuk olarak çağırdı. Sunucu ünlü, şaka kaldırırsa salon seninle.": "« {0} » t'a invité. L'animateur est célèbre ; si tu sais encaisser une blague, le public est à toi.",
  "Sunucuya canlı yayında armbar gösterdin. Klip her yerde.": "Tu as montré une clé de bras à l'animateur en direct. L'extrait est partout.",
  "📰 Dergi Kapağı": "📰 Couverture de magazine",
  "{0} dergisi seni kapağa koymak istiyor. Bir günlük çekim, büyük bir röportaj.": "Le magazine {0} te veut en couverture. Une journée de shooting et une grande interview.",
  "Kapak büfelerde tükendi. Bir kopyası salonun duvarında.": "Le numéro a été épuisé en kiosque. Un exemplaire est accroché au mur de la salle.",
  "📺 Dizi Konuk Rolü": "📺 Rôle invité à la télé",
  "Sevilen dizi “{0}” bir bölümde seni kendini oynaman için istiyor. İki hafta çekim.": "La série à succès « {0} » veut que tu joues ton propre rôle dans un épisode. Deux semaines de tournage.",
  "Sahnen sosyal medyada dolaştı. Senaristler “bir sezon daha gel” diyor.": "Ta scène a fait le tour des réseaux. Les scénaristes te veulent la saison prochaine.",
