  "Reddet, odak kafeste": "Refuser, te concentrer sur la cage",
  "“Şu an tek işim dövüşmek.” Hocan bu cevabı çok sevdi. Motivasyon +1.": "« En ce moment, mon seul travail, c'est de combattre. » Ton entraîneur a adoré cette réponse. Motivation +1.",
