  "Serbest": "Libre",
  "Ne canın isterse. Kilo vermek zorlaşır, iyileşme biraz yavaşlar.": "Tout ce que tu veux. La coupe de poids devient plus dure et la récupération ralentit un peu.",
  "Ev yemekleri, ölçülü porsiyon. Etkisi yok.": "Cuisine maison, portions raisonnables. Aucun effet.",
  "Hazır diyet menüsü: maç başı ${0}. Kilo vermek kolaylaşır, iyileşme hızlanır.": "Plan diététique en meal prep : {0} $ par combat. La coupe de poids devient plus facile et la récupération plus rapide.",
  "Değişken": "Irrégulier",
  "Geç saatlere kadar sosyal hayat: maç başı popülerlik +1, iyileşme normal.": "Vie sociale jusque tard : popularité +1 par combat, récupération normale.",
  "Düzenli": "Régulier",
  "Her gece 8 saat, telefon yatak odasına girmiyor: iyileşme hızlanır.": "Huit heures chaque nuit, pas de téléphone dans la chambre : récupération plus rapide.",
