  "🦴 {0} iyileşti ama izi kaldı: {1} bölgesi artık hassas.": "🦴 {0} a guéri mais a laissé une trace : ton {1} est désormais fragile.",
  "Gelişim çağı": "Années de développement",
  "Vücudun hızla öğreniyor: kamptan en çok gelişimi bu yaşlarda alırsın.": "Ton corps apprend vite : à cet âge, tu tires le maximum des camps.",
  "Zirve yılları": "Années de pointe",
  "Hız, güç ve kondisyon en iyi hâlinde. Kemer için en doğru zaman.": "Vitesse, puissance et cardio au top. Le bon moment pour viser une ceinture.",
  "Gelişim yavaşlıyor ama kafes zekân her maçla artıyor.": "La progression ralentit, mais ton QI de combat grandit à chaque combat.",
  "Gün batımı": "Crépuscule",
  "Her yıl hız ve çene biraz düşer, IQ artar. Akıllı dövüşmek zorundasın.": "Chaque année, la vitesse et le menton baissent un peu et le QI augmente. Il faut combattre intelligemment.",
  "Yaşın, izlerin ve günlük rutinin. Küçük seçimler, uzun bir kariyerde büyük fark yaratır.": "Ton âge, tes cicatrices et ta routine. Les petits choix font une grande différence sur une longue carrière.",
