  "Her iz kampta sakatlık riskini biraz artırır. Fizyoterapist bu riski azaltır.": "Chaque cicatrice augmente un peu le risque de blessure en camp. Un kiné réduit ce risque.",
  "Vücudunda kalıcı iz yok. Ağır sakatlıklar iyileşirken bazen iz bırakır.": "Aucune cicatrice durable. Les blessures graves laissent parfois une trace en guérissant.",
