  "Gece düzenlemek için kontratı süren en az 4 dövüşçü gerekiyor. Keşif sekmesinden imzala.": "Il te faut au moins 4 combattants sous contrat pour organiser une soirée. Recrutes-en dans l'onglet Recrutement.",
