  "Kamera yokken de bu kadar cesur musun? Kafeste göreceğiz.": "Tu es aussi courageux quand les caméras sont éteintes ? On verra dans la cage.",
  "Senin videolarını izledim. Açığını buldum bile. 😴": "J'ai regardé tes vidéos. J'ai déjà trouvé ta faiblesse. 😴",
  "Ailene söyle, maçı izlemesinler. Üzülmesinler.": "Dis à ta famille de ne pas regarder. Je ne veux pas les rendre tristes.",
  "Basın toplantısında gülüyordun. Kafeste gülemeyeceksin.": "Tu riais à la conférence de presse. Tu ne riras pas dans la cage.",
  "Bu maçtan sonra kimse adını hatırlamayacak.": "Après ce combat, plus personne ne se souviendra de ton nom.",
  "Selam. Kampın iyi geçsin, sağlıklı gel. Kafeste en iyi hâllerimizle karşılaşalım. 🤝": "Salut. Bon camp, arrive en bonne santé. Retrouvons-nous au meilleur de notre forme dans la cage. 🤝",
  "Kariyerini uzun zamandır izliyorum. Bu maç ikimiz için de büyük fırsat. Başarılar.": "Je suis ta carrière depuis longtemps. Ce combat est une grande chance pour nous deux. Bonne chance.",
  "Basında ne derlerse desinler, sana saygım var. Maç günü görüşürüz.": "Quoi que dise la presse, je te respecte. À la soirée du combat.",
  "Görüldü bırak": "Laisser en vu",
