  "Cevap vermedin. Sinirini kampa sakladın: motivasyon +1.": "Tu n'as pas répondu. Tu as gardé la colère pour le camp : motivation +1.",
  "DM kavgası": "Guerre en DM",
  "Mesajlaşma kızıştı, kulise sızdı. Maçın gündemi yükseldi. Takipçi {0}.": "L'échange s'est envenimé et a fuité. Le buzz du combat a augmenté. Abonnés {0}.",
  "İfşa": "Démasqué",
  "Ekran görüntüsü yayıldı, herkes rakibin tehdidini konuşuyor. Takipçi {0}.": "La capture a circulé, tout le monde parle de la menace. Abonnés {0}.",
  "Saygıyla karşılık ver 🤝": "Répondre avec respect 🤝",
  "Alay et 😏": "Se moquer de lui 😏",
  "Karşılıklı saygı. İçin rahat, kampa odaklandın: motivasyon +1, popülerlik +1.": "Respect mutuel. Esprit clair, concentré sur le camp : motivation +1, popularité +1.",
  "Alaycı DM": "DM moqueur",
  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "Ton adversaire l'a publié : « J'ai montré du respect, et voilà ce que j'ai reçu. » Le buzz a augmenté, mais certains fans se sont refroidis. Abonnés {0}.",
  "Promotör ofisi": "Bureau du promoteur",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Il faut vendre ce combat. On peut organiser une tournée presse dans 3 villes la semaine prochaine. Fatigant, mais les billets vont s'envoler. Tu es partant ?",
  "Varım, tura çıkalım": "Je suis partant, en tournée",
  "Kampı bölmem": "Je n'interromps pas le camp",
  "Basın turu": "Tournée presse",
  "Tur olay oldu, biletler kapışılıyor. Ama yol yorgunluğu kampı biraz bozdu: motivasyon -1. Takipçi {0}.": "La tournée a cartonné, les billets s'envolent. Mais les déplacements t'ont usé : motivation -1. Abonnés {0}.",
  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "Le promoteur a ronchonné, mais tu as protégé ton camp : motivation +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "Un dîner en tête-à-tête ce soir avant le début du camp ? Après, je ne te verrai pas pendant des semaines. ❤️",
  "Tabii, rezervasyon benden": "Bien sûr, je réserve une table",
  "Maçtan sonra telafi ederim": "Je me rattraperai après le combat",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Une belle soirée. Tu entres en camp l'esprit clair : motivation +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "« Promis ? » Tu as promis. N'oublie pas après le combat.",
  "Annem": "Maman",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "J'ai appris par la voisine que tu as encore un combat. Mange correctement, ne t'affame pas pour le poids. Je prie pour toi.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Ton père regarde sur grand écran, il a invité tout le quartier. Prends soin de toi, mon cœur.",
  "Hemen ara 📞": "Appeler tout de suite 📞",
  "“Merak etme anne” yaz": "Écrire « Ne t'inquiète pas, maman »",
  "Yarım saat konuştunuz. Sesini duymak iyi geldi: motivasyon +1.": "Vous avez parlé une demi-heure. Entendre sa voix t'a fait du bien : motivation +1.",
  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Elle a écrit : « D'accord mon cœur, que Dieu te garde. » ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Je peux imiter le style de ton adversaire. Sparring en plus ce soir après la fermeture de la salle ? 🥊",
  "Yapalım": "Allons-y",
  "Bu akşam dinlenmem lazım": "J'ai besoin de repos ce soir",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Sparring dur mais utile. Votre lien a grandi, tu as un peu morflé (santé −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Il a écrit « Ok frérot. » Il semble un peu vexé.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Tu as eu de la chance. On le sait tous les deux. À la revanche, tu verras la vérité.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Tu étais meilleur ce soir, bravo. J'aimerais une revanche un jour, mais d'abord je vais me reconstruire. 🤝",
  "Saygılar, iyi dövüştün": "Respect, beau combat",
