  "Ne zaman istersen": "Quand tu veux",
  "Mesajı paylaştı: “Gerçek bir şampiyon adayı.” Popülerlik +1.": "Il l'a partagé : « Un vrai prétendant au titre. » Popularité +1.",
  "Ekran görüntüsü taraftar sayfalarında dolaşıyor. Takipçi {0}.": "La capture est partout sur les pages de fans. Abonnés {0}.",
  "Rekabet kızışıyor. Bir gün yine karşılaşırsanız ortalık yanar.": "La rivalité monte. Si vous vous retrouvez un jour, ça va chauffer.",
  "Hocam": "Entraîneur",
  "Kafana takma. Yarın sabah salona erken gel, maçı birlikte izleyelim. Neyi yanlış yaptığımızı ben de görmek istiyorum.": "N'y pense plus. Viens tôt à la salle demain, on regardera le combat ensemble. Je veux voir aussi ce qu'on a mal fait.",
