  "Hey şampiyon, büyük hayranınım! Bir sonraki maçına gelmek istiyorum. Bilet ayarlayabilir misin? 🙏": "Salut champion, énorme fan ! Je veux venir à ton prochain combat. Tu peux m'avoir un billet ? 🙏",
